import { type ClassValue, clsx } from 'clsx'
import { createElement, type ReactNode } from 'react'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs))
}

/**
 * Convierte el marcador `*palabra*` de data.json en `<em>palabra</em>`.
 * Convención de contenido: el copy de negocio vive en data.json y el énfasis
 * tipográfico se marca con asteriscos (nunca con HTML).
 */
export function emphasize(text: string): ReactNode[] {
	return text.split(/(\*[^*]+\*)/g).map((part, i) => {
		if (part.startsWith('*') && part.endsWith('*')) {
			return createElement('em', { key: i }, part.slice(1, -1))
		}
		return part
	})
}

