import { useState } from 'react'
import { trackEvent } from '@/lib/analytics'
import { FORMSPREE_ENDPOINT } from '@/lib/utils'

export interface NewsletterFormState {
	email: string
	website: string
}

const EMPTY: NewsletterFormState = {
	email: '',
	website: '',
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

/**
 * Lógica del formulario de newsletter del footer (honeypot + validación de
 * correo + envío a Formspree con marcador `tipo: newsletter` para filtrar
 * en el mismo form del contacto). El contenido (títulos, gracias, legal)
 * vive en data.json → Site.newsletter.
 */
export function useNewsletterForm() {
	const [formData, setFormData] = useState<NewsletterFormState>(EMPTY)
	const [emailError, setEmailError] = useState('')
	const [isSubmitting, setIsSubmitting] = useState(false)
	const [submitStatus, setSubmitStatus] = useState<'success' | 'error' | null>(null)

	const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		const { name, value } = e.target
		setFormData((prev) => ({ ...prev, [name]: value }))
		if (name === 'email') {
			setEmailError(value && !EMAIL_RE.test(value) ? 'Ingresa un correo válido.' : '')
		}
	}

	const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
		e.preventDefault()
		if (formData.website) return
		if (!formData.email) {
			setEmailError('Ingresa tu correo para suscribirte.')
			return
		}
		if (!EMAIL_RE.test(formData.email)) {
			setEmailError('Ingresa un correo válido.')
			return
		}
		setIsSubmitting(true)
		setSubmitStatus(null)
		try {
			const response = await fetch(FORMSPREE_ENDPOINT, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({
					...formData,
					tipo: 'newsletter',
					_subject: 'Nuevo suscriptor · Newsletter',
				}),
			})
			if (response.ok) {
				trackEvent('newsletter_signup')
				setSubmitStatus('success')
				setFormData(EMPTY)
			} else {
				setSubmitStatus('error')
			}
		} catch {
			setSubmitStatus('error')
		} finally {
			setIsSubmitting(false)
		}
	}

	return { formData, emailError, isSubmitting, submitStatus, handleChange, handleSubmit }
}
