/**
 * Eventos de conversión sobre el GA4 ya cargado en index.html (gtag.js).
 * No-op seguro cuando gtag no está disponible (tests, ad-blockers, SSR).
 */
declare global {
	interface Window {
		gtag?: (command: 'event', name: string, params?: Record<string, string>) => void
	}
}

export function trackEvent(name: string, params?: Record<string, string>) {
	window.gtag?.('event', name, params)
}

/**
 * Registra clics en cualquier enlace de WhatsApp (wa.me) con el contexto de la
 * sección que lo contiene (hero, modalidades, cursos, modal de add-on, etc.).
 * Devuelve la función de limpieza para usarla en un useEffect.
 */
export function initWhatsAppTracking() {
	const onClick = (e: MouseEvent) => {
		const anchor = (e.target as HTMLElement | null)?.closest?.('a[href*="wa.me"]')
		if (!anchor) return
		const container = anchor.closest('section, header, footer, [role="dialog"]')
		const context =
			container?.id ||
			(container?.getAttribute('role') === 'dialog' ? 'addon-modal' : null) ||
			container?.tagName.toLowerCase() ||
			'unknown'
		trackEvent('whatsapp_click', { link_context: context })
	}
	document.addEventListener('click', onClick)
	return () => document.removeEventListener('click', onClick)
}
