import { ArrowRight, ArrowUp } from 'lucide-react'
import type { CSSProperties } from 'react'
import { useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { Link } from 'react-router-dom'
import { StarMark } from '@/components/BrandIcons'
import { useSmoothScroll } from '@/components/SmoothScroll'
import JsonData from '@/data/data.json'
import { useReveal } from '@/hooks/useReveal'
import { emphasize } from '@/lib/utils'
import '@/home/meridian.css'

/* JSON-LD para rich results de Google: ItemList de Course, derivado
   exclusivamente de los datos reales en data.json. */
const courseSchema = (cursos: typeof JsonData.Cursos) => {
	const toDuration = (d: string) => {
		const match = d.match(/(\d+)\s*horas?/i)
		return match ? `PT${match[1]}H` : undefined
	}

	return {
		'@context': 'https://schema.org',
		'@type': 'ItemList',
		name: 'Capacitaciones SAP Business One | Cygnus Consulting',
		itemListElement: cursos.map((curso, i) => {
			const mode = []
			if (curso.modalidad.includes('Virtual')) mode.push('online')
			if (curso.modalidad.includes('Presencial')) mode.push('onsite')
			return {
				'@type': 'ListItem',
				position: i + 1,
				item: {
					'@type': 'Course',
					name: curso.titulo,
					description: curso.descripcion,
					...(toDuration(curso.duracion) && { timeRequired: toDuration(curso.duracion) }),
					courseMode: mode.length === 1 ? mode[0] : mode,
					provider: {
						'@type': 'Organization',
						name: 'Cygnus Consulting SAC',
					},
				},
			}
		}),
	}
}

export default function CursosPage() {
	const { lenis } = useSmoothScroll()
	const pageRef = useReveal<HTMLDivElement>()

	const data = JsonData
	const cursoPage = data.CursosPage
	const [courseLevel, setCourseLevel] = useState(cursoPage.filterAll)
	const cursos = data.Cursos ?? []
	const site = data.Site
	const meta = data.Meta
	/* Los niveles de filtro se derivan de los datos (única fuente): */
	const courseLevels = [cursoPage.filterAll, ...new Set(cursos.map((c) => c.nivel))]
	const filteredCursos =
		courseLevel === cursoPage.filterAll ? cursos : cursos.filter((c) => c.nivel === courseLevel)
	const waLink = data.Header.whatsapp
	const revealDelay = (i: number): CSSProperties =>
		({ '--reveal-delay': `${i * 60}ms` }) as CSSProperties

	return (
		<div className="mrn-page" ref={pageRef}>
			<Helmet>
				<title>{meta.cursos.title}</title>
				<meta name="description" content={meta.cursos.description} />
				<link rel="canonical" href={`${site.url}/cursos`} />
				<meta property="og:type" content="website" />
				<meta property="og:url" content={`${site.url}/cursos`} />
				<meta property="og:title" content={meta.cursos.title} />
				<meta property="og:description" content={meta.cursos.description} />
				<meta property="og:locale" content="es_PE" />
				<meta property="og:site_name" content={site.brand} />
				<meta property="og:image" content={`${site.url}/img/og-cover.png`} />
				<meta name="twitter:card" content="summary_large_image" />
				<meta name="twitter:title" content={meta.cursos.title} />
				<meta name="twitter:description" content={meta.cursos.description} />
				<meta name="twitter:image" content={`${site.url}/img/og-cover.png`} />
				<script type="application/ld+json">{JSON.stringify(courseSchema(cursos))}</script>
			</Helmet>

			{/* ---------- Header ---------- */}
			<header className="mrn-header">
				<div className="mrn-header__inner">
					<Link to="/" className="mrn-header__brand">
						<StarMark size={18} />
						<span className="mrn-header__word">{site.brand}</span>
						<span className="mrn-header__sub">{site.tagline}</span>
					</Link>
					<nav className="mrn-header__nav" aria-label="Secciones">
						<Link to="/" className="mrn-navlink">
							{cursoPage.navInicio}
						</Link>
						<span className="mrn-navlink" aria-current="page">
							{cursoPage.navCursos}
						</span>
					</nav>
					<div className="mrn-header__actions">
						<a
							href={waLink}
							target="_blank"
							rel="noopener noreferrer"
							className="mrn-btn mrn-btn--primary mrn-btn--sm"
						>
							{cursoPage.cta}
						</a>
					</div>
				</div>
			</header>

			<main>
				{/* ---------- Catálogo ---------- */}
				<section className="mrn-section mrn-section--pale" aria-label="Catálogo de cursos">
					<div className="mrn-section__head">
						<span className="mrn-mono mrn-section__tag" data-reveal>
							{cursoPage.tag}
						</span>
						<h1 className="mrn-section__title" data-reveal style={revealDelay(1)}>
							{emphasize(cursoPage.title)}
						</h1>
						<p className="mrn-section__intro" data-reveal style={revealDelay(2)}>
							{cursoPage.intro}
						</p>
						<fieldset className="mrn-filters" data-reveal style={revealDelay(3)}>
							<legend className="sr-only">Filtrar cursos por nivel</legend>
							{courseLevels.map((level) => (
								<button
									key={level}
									type="button"
									className={`mrn-chip${courseLevel === level ? ' is-active' : ''}`}
									onClick={() => setCourseLevel(level)}
									aria-pressed={courseLevel === level}
								>
									{level}
								</button>
							))}
						</fieldset>
					</div>
					<div className="mrn-research" key={courseLevel}>
						{filteredCursos.map((curso, i) => (
							<article
								key={curso.id}
								className="mrn-research__row"
								style={{ '--i': i } as CSSProperties}
							>
								<div className="mrn-research__title">
									<h2>{curso.titulo}</h2>
									<p>{curso.descripcion}</p>
								</div>
								<div className="mrn-research__pills">
									<span className="mrn-pill mrn-pill--coral">{curso.nivel}</span>
									<span className="mrn-pill">{curso.modalidad}</span>
								</div>
								<div className="mrn-research__meta">
									<span className="mrn-mono">{curso.duracion.toUpperCase()}</span>
									<a
										href={curso.whatsapp}
										target="_blank"
										rel="noopener noreferrer"
										className="mrn-btn mrn-btn--pill mrn-btn--sm"
										aria-label={`Consultar curso ${curso.titulo}`}
									>
										{cursoPage.cta}
										<ArrowRight size={14} />
									</a>
								</div>
							</article>
						))}
					</div>
				</section>
			</main>

			{/* ---------- Footer ---------- */}
			<footer className="mrn-footer">
				<div className="mrn-footer__legal">
					<span>
						© {new Date().getFullYear()} {site.name}
					</span>
					<button
						type="button"
						className="mrn-footer__top"
						onClick={() => lenis?.scrollTo(0, { duration: 1.2 })}
					>
						<ArrowUp size={14} />
						{cursoPage.backTop}
					</button>
				</div>
			</footer>
		</div>
	)
}
