import { useState } from 'react'
import { trackEvent } from '@/lib/analytics'
import { FORMSPREE_ENDPOINT } from '@/lib/utils'

export interface ContactFormState {
	name: string
	email: string
	company: string
	phone: string
	modalidad: string
	message: string
	website: string
}

const EMPTY: ContactFormState = {
	name: '',
	email: '',
	company: '',
	phone: '',
	modalidad: '',
	message: '',
	website: '',
}

/**
 * Lógica compartida del formulario de contacto (honeypot + validación de
 * correo + envío a Formspree). Las versiones de diseño solo se encargan del
 * markup y los estilos.
 */
export function useContactForm() {
	const [formData, setFormData] = useState<ContactFormState>(EMPTY)
	const [emailError, setEmailError] = useState('')
	const [isSubmitting, setIsSubmitting] = useState(false)
	const [submitStatus, setSubmitStatus] = useState<'success' | 'error' | null>(null)

	const handleChange = (
		e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
	) => {
		const { name, value } = e.target
		setFormData((prev) => ({ ...prev, [name]: value }))
		if (name === 'email') {
			const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)
			setEmailError(value && !valid ? 'Ingresa un correo válido.' : '')
		}
	}

	const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
		e.preventDefault()
		if (formData.website || emailError) return
		setIsSubmitting(true)
		setSubmitStatus(null)
		try {
			const response = await fetch(FORMSPREE_ENDPOINT, {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify(formData),
			})
			if (response.ok) {
				trackEvent('generate_lead', { form: 'contact', modalidad: formData.modalidad || 'none' })
				setSubmitStatus('success')
				setFormData(EMPTY)
			} else {
				setSubmitStatus('error')
			}
		} catch {
			setSubmitStatus('error')
		} finally {
			setIsSubmitting(false)
		}
	}

	return { formData, emailError, isSubmitting, submitStatus, handleChange, handleSubmit }
}
