import { useEffect, useRef } from 'react'

/**
 * Observa los elementos `[data-reveal]` dentro del contenedor y les agrega
 * la clase `.is-in` la primera vez que entran al viewport. El CSS de cada
 * versión define la transición (opacity + translateY) y el retraso opcional
 * vía `--reveal-delay`.
 */
export function useReveal<T extends HTMLElement>() {
	const ref = useRef<T>(null)

	useEffect(() => {
		const root = ref.current
		if (!root) return

		const els = Array.from(root.querySelectorAll<HTMLElement>('[data-reveal]'))
		if (els.length === 0) return

		if (typeof IntersectionObserver === 'undefined') {
			els.forEach((el) => {
				el.classList.add('is-in')
			})
			return
		}

		const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches

		if (prefersReduced) {
			els.forEach((el) => {
				el.classList.add('is-in')
			})
			return
		}

		const io = new IntersectionObserver(
			(entries) => {
				for (const entry of entries) {
					if (entry.isIntersecting) {
						entry.target.classList.add('is-in')
						io.unobserve(entry.target)
					}
				}
			},
			{ threshold: 0.15, rootMargin: '0px 0px -6% 0px' }
		)

		els.forEach((el) => {
			io.observe(el)
		})
		return () => io.disconnect()
	}, [])

	return ref
}
