/* Estado por servicio, derivado del tablero del hero (data.json Signals) — sin
   datos inventados. Cada hero-photo-card usa la señal honesta de su servicio. */
function serviceSignal(signals: SignalData[], name: string) {
	const first = name.split(' ')[0]
	const norm = first === 'Capacitaciones' ? 'CAPACITACIÓN' : first.toUpperCase()
	return signals.find((s) => s.name === norm) ?? signals[0]
}

function initials(name: string) {
	return name
		.split(' ')
		.map((part) => part.charAt(0))
		.join('')
		.slice(0, 2)
		.toUpperCase()
}

/* JSON-LD Organization derivado exclusivamente de data.json (única fuente). */
const organizationSchema = (d: SiteData) => ({
	'@context': 'https://schema.org',
	'@type': 'Organization',
	name: d.Site.name,
	alternateName: d.Site.brand,
	url: d.Site.url,
	description: d.Meta.home.description,
	foundingDate: d.About.foundingYear,
	address: {
		'@type': 'PostalAddress',
		streetAddress: d.Contact.address,
		addressLocality: 'Lima',
		addressRegion: 'Lima',
		addressCountry: 'PE',
	},
	telephone: d.Contact.phone,
	email: d.Contact.email,
	sameAs: [d.Contact.facebook, d.Contact.linkedin, d.Contact.youtube],
	areaServed: { '@type': 'Country', name: 'Perú' },
	hasOfferCatalog: {
		'@type': 'OfferCatalog',
		name: 'Servicios SAP Business One',
		itemListElement: d.Services.map((s, i) => ({
			'@type': 'Offer',
			position: i + 1,
			itemOffered: { '@type': 'Service', name: s.name, description: s.text },
		})),
	},
})

