import Lenis from 'lenis'
import {
	createContext,
	type ReactNode,
	useContext,
	useEffect,
	useMemo,
	useRef,
	useState,
} from 'react'
import { useLocation } from 'react-router-dom'

interface SmoothScrollContextValue {
	lenis: Lenis | null
	ready: boolean
}

const SmoothScrollContext = createContext<SmoothScrollContextValue>({
	lenis: null,
	ready: false,
})

export const useSmoothScroll = () => useContext(SmoothScrollContext)

interface SmoothScrollProps {
	children: ReactNode
}

export default function SmoothScroll({ children }: SmoothScrollProps) {
	const lenisRef = useRef<Lenis | null>(null)
	const [ready, setReady] = useState(false)
	const location = useLocation()
	const isBlog = location.pathname.startsWith('/blog')

	useEffect(() => {
		if (isBlog) return

		const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches

		const lenis = new Lenis({
			duration: prefersReduced ? 1 : 2.4,
			easing: (t: number) => Math.min(1, 1.001 - 2 ** (-8 * t)),
			orientation: 'vertical',
			gestureOrientation: 'vertical',
			smoothWheel: !prefersReduced,
			touchMultiplier: 1.2,
			infinite: false,
		})

		lenisRef.current = lenis
		setReady(true)

		// rAF propio en vez del ticker de GSAP: requestAnimationFrame entrega
		// el tiempo en ms, que es lo que espera lenis.raf.
		let rafId = 0
		const raf = (time: number) => {
			lenis.raf(time)
			rafId = requestAnimationFrame(raf)
		}
		rafId = requestAnimationFrame(raf)

		return () => {
			setReady(false)
			cancelAnimationFrame(rafId)
			lenis.destroy()
			lenisRef.current = null
		}
	}, [isBlog])

	// biome-ignore lint/correctness/useExhaustiveDependencies: location.pathname es el trigger intencional para volver al top al cambiar de ruta
	useEffect(() => {
		lenisRef.current?.scrollTo(0, { immediate: true })
	}, [location.pathname])

	const value = useMemo<SmoothScrollContextValue>(
		() => ({ lenis: lenisRef.current, ready }),
		[ready]
	)

	return <SmoothScrollContext.Provider value={value}>{children}</SmoothScrollContext.Provider>
}
